import type { OkfRuleId } from '../psf-rule-meta.ts';
import { fileNameFor, PSF_SCHEMA_DIR, psfSchemaPathFor } from './paths.ts';
import { PSF_FRONTMATTER_REGISTRY } from './registry.ts';

export { PSF_SCHEMA_DIR, psfSchemaPathFor };

const GENERATED_NOTE =
  'Generated by the Palimpsest `psf` lint plugin — do not edit. The plugin validates ' +
  'from its own compiled copy and never reads this file, so changes here have no effect ' +
  'and are overwritten when the server restarts. This describes an external format ' +
  '(Google’s Palimpsest Format); to change what is enforced, change the rule ' +
  'toggles under Settings → this project → Plugins → OKF.';

export interface OkfSchemaFile {
  readonly path: string;
  readonly ruleId: OkfRuleId;
  readonly contents: string;
}

export function renderOkfSchemaFiles(): OkfSchemaFile[] {
  return PSF_FRONTMATTER_REGISTRY.map((entry) => ({
    path: `${PSF_SCHEMA_DIR}/${fileNameFor(entry.id)}`,
    ruleId: entry.id,
    contents: `${JSON.stringify({ $comment: GENERATED_NOTE, ...entry.schema }, null, 2)}\n`,
  }));
}
